&lt;li data-leveltext="" data-font="Symbol" data-listid="6" data-list-defn-props="{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}" data-aria-posinset="13" data-aria-level="1"&gt;&lt;span data-contrast="auto"&gt;&lt;span data-ccp-parastyle="p1" data-ccp-parastyle-defn="{&amp;quot;ObjectId&amp;quot;:&amp;quot;5608de39-acc8-52c5-8723-06e2503f1031|1&amp;quot;,&amp;quot;ClassId&amp;quot;:1073872969,&amp;quot;Properties&amp;quot;:[201342446,&amp;quot;1&amp;quot;,201342447,&amp;quot;5&amp;quot;,201342448,&amp;quot;3&amp;quot;,201342449,&amp;quot;1&amp;quot;,469777841,&amp;quot;Times New Roman&amp;quot;,469777842,&amp;quot;Times New Roman&amp;quot;,469777843,&amp;quot;Times New Roman&amp;quot;,469777844,&amp;quot;Times New Roman&amp;quot;,201341986,&amp;quot;1&amp;quot;,469769226,&amp;quot;Times New Roman&amp;quot;,268442635,&amp;quot;24&amp;quot;,469775450,&amp;quot;p1&amp;quot;,201340122,&amp;quot;2&amp;quot;,134233614,&amp;quot;true&amp;quot;,469778129,&amp;quot;p1&amp;quot;,335572020,&amp;quot;1&amp;quot;,335559705,&amp;quot;2057&amp;quot;,134233118,&amp;quot;true&amp;quot;,134233117,&amp;quot;true&amp;quot;,469778324,&amp;quot;Normal&amp;quot;]}"&gt;Significant&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle="p1"&gt;experience&lt;/span&gt;&lt;span data-ccp-parastyle="p1"&gt;&amp;nbsp;developing and deploying manufacturing test solutions for high-performance servers, accelerators (GPU-class), or comparable large-scale&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle="p1"&gt;compute&lt;/span&gt;&lt;span data-ccp-parastyle="p1"&gt;&amp;nbsp;hardware.&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext="" data-font="Symbol" data-listid="6" data-list-defn-props="{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}" data-aria-posinset="13" data-aria-level="1"&gt;Strong &lt;span data-ccp-parastyle="p1"&gt;technical leadership as an individual contributor,&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle="p1"&gt;with experience&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle="p1"&gt;owning&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle="p1"&gt;substantial&lt;/span&gt;&lt;span data-ccp-parastyle="p1"&gt;&amp;nbsp;technical workstreams&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle="p1"&gt;and&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle="p1"&gt;collaborating&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle="p1"&gt;across multiple teams without direct line management responsibility.&lt;/span&gt;&lt;/li&gt;
